7S$words$,E'\n') value LOOP prefix_i:=strpos('0123456789abcdefghijklmnopqrstuvwxyz',left(entry,1))-1;IF prefix_i<0 OR prefix_i>length(prior) THEN RAISE EXCEPTION 'ptown_words:dictionary_encoding';END IF;word_i:=left(prior,prefix_i)||substr(entry,2);INSERT INTO private.ptown_words_lexicon VALUES('enable2k/1',word_i);prior:=word_i;END LOOP;IF (SELECT count(*) FROM private.ptown_words_lexicon)<>173528 OR (SELECT encode(extensions.digest(string_agg(word,E'\n' ORDER BY word COLLATE "C")||E'\n','sha256'),'hex') FROM private.ptown_words_lexicon WHERE version='enable2k/1')<>'d5ec7b3b1d35db798cee044fe3ec37e7cc0a96a00dee5695ad34c767f1797925' THEN RAISE EXCEPTION 'ptown_words:dictionary_integrity';END IF;END $decode$;
ALTER PUBLICATION supabase_realtime ADD TABLE public.ptown_words_revisions;
SELECT cron.schedule('ptown-words-recovery','5 seconds',$job$SET statement_timeout='3s'; SELECT private.ptown_words_recover()$job$);
